  1	// SPDX-License-Identifier: GPL-2.0
  2	/*
  3	 * weaknet_cpu_stat.c - WeakNet 实验性 per-CPU 统计采集内核模块
  4	 *
  5	 * 定位：B1 实验路径。不进 tools/ci.sh、不进 OTA manifest、不注册
  6	 * IMonitorPlugin、不新增 D-Bus 方法。仅供板端手工 make / insmod 验证。
  7	 *
  8	 * 数据通路：
  9	 *   hrtimer(1s) -> 逐 CPU 读取 kcpustat / idle / iowait 到私有缓冲区
 10	 *              -> seqlock 保护下 memcpy 到共享缓冲区
 11	 *              -> 用户态 mmap 只读访问
 12	 *
 13	 * 与参考实现（monitor_system worker/src/kmod/cpu_stat_collector.c）的差异：
 14	 *   D1  私有缓冲区 + seqlock 代次号，消除跨字段撕裂读
 15	 *   D2  vmalloc_user + remap_vmalloc_range，去掉错误的 pgprot_noncached
 16	 *   D3  输出纳秒而非 jiffies。实测澄清两点（本板 CONFIG_HZ=250、
 17	 *       CONFIG_TICK_CPU_ACCOUNTING=y）：
 18	 *         a) kcpustat 的 busy 类字段本就按 TICK_NSEC(1e9/HZ=4ms) 累加，
 19	 *            源实现的 nsec_to_jiffies() 除以 4e6 是**无损**的，
 20	 *            所以「转 jiffies 引入量化误差」对 busy 类不成立。
 21	 *         b) 真正的精度收益在 idle / iowait：它们来自
 22	 *            get_cpu_idle_time_us() 的**微秒**值，源实现接着用
 23	 *            usecs_to_jiffies() 又压回 4ms；本实现保留微秒精度。
 24	 *       guest / guest_nice 原样导出，由用户态按 /proc/stat 口径排除在
 25	 *       busy 之外（user 已含 guest、nice 已含 guest_nice）。
 26	 *   D4  头部携带 nr_cpus，用户态不再硬编码上限
 27	 *   D5  每条记录带 online 标记，可区分离线 CPU
 28	 *   D6  open 校验 CAP_SYS_ADMIN
 29	 *   D7  Makefile 的 KDIR 可覆盖，支持交叉编译
 30	 */
 31	
 32	#include <linux/module.h>
 33	#include <linux/kernel.h>
 34	#include <linux/init.h>
 35	#include <linux/fs.h>
 36	#include <linux/cdev.h>
 37	#include <linux/device.h>
 38	#include <linux/mm.h>
 39	#include <linux/vmalloc.h>
 40	#include <linux/hrtimer.h>
 41	#include <linux/ktime.h>
 42	#include <linux/kernel_stat.h>
 43	#include <linux/cpumask.h>
 44	#include <linux/tick.h>
 45	#include <linux/version.h>
 46	#include <linux/capability.h>
 47	#include <linux/sched.h>
 48	
 49	#include "weaknet_kmod_abi.h"
 50	
 51	#define DEVICE_NAME "weaknet_cpu_stat"
 52	#define CLASS_NAME  DEVICE_NAME
 53	
 54	#define NSEC_PER_USEC_LOCAL 1000ULL
 55	
 56	MODULE_LICENSE("GPL");
 57	MODULE_AUTHOR("tanqf");
 58	MODULE_DESCRIPTION("WeakNet experimental per-CPU stats collector via mmap");
 59	MODULE_VERSION("0.1.0");
 60	
 61	static dev_t g_dev;
 62	static struct cdev g_cdev;
 63	static struct class *g_class;
 64	static struct device *g_device;
 65	
 66	static struct wn_cpu_snapshot *g_shared;  /* 用户态可见的映射区 */
 67	static struct wn_cpu_snapshot *g_priv;    /* 内核私有工作区 */
 68	static size_t g_map_size;
 69	
 70	static struct hrtimer g_timer;
 71	static ktime_t g_interval;
 72	
 73	/*
 74	 * tickless 感知的空闲时间。NO_HZ_IDLE 下 kcpustat 的 idle 不会随 tick
 75	 * 推进，必须优先取 tick 子系统的精确值，失败才回落累计值。
 76	 *
 77	 * 【离线 CPU 必须绕开 tick 路径】
 78	 *
 79	 * get_cpu_idle_time_us() 内部只判 tick_nohz_active，**不判 cpu_online()**，
 80	 * 它读的是 per_cpu(tick_cpu_sched, cpu) 的 idle_sleeptime / idle_entrytime。
 81	 * 而 CPU 下线时 tick_cancel_sched_timer() 会执行
 82	 *
 83	 *     memset(ts, 0, sizeof(*ts));
 84	 *
 85	 * 把这两个字段连同 idle_active 一起清零。清零后本函数走 else 分支：
 86	 * idle = 0 + (ktime_get() - 0)，也就是**返回自开机以来的绝对时间**，
 87	 * 且每次采样都在增长。实测（11-05，CPU6/CPU7 离线）该值从 1533 s 跳到
 88	 * 1.58 s，之后每 2 秒 +2.00 s——它跟的是 wall clock，不是 CPU 空闲。
 89	 *
 90	 * 危害：用户态用 (idle_a - idle_b) 算区间增量，会得到负数或远超 100%
 91	 * 的离谱使用率。而且这个错误值不会返回 -1，所以下面的回落分支根本不触发。
 92	 *
 93	 * 已实测确认（11-05）：CPU 离线期间 kcpustat 的纯累计字段
 94	 * （user/system/softirq 等）是完全冻结的。因此对离线 CPU 直接读
 95	 * kcpustat 既安全又语义正确——报的是该 CPU 下线前的最终累计值。
 96	 */
 97	static u64 wn_idle_ns(int cpu)
 98	{
 99		u64 us;
100	
101		if (!cpu_online(cpu))
102			return kcpustat_cpu(cpu).cpustat[CPUTIME_IDLE];
103	
104		us = get_cpu_idle_time_us(cpu, NULL);
105		if (us != (u64)-1)
106			return us * NSEC_PER_USEC_LOCAL;
107		return kcpustat_cpu(cpu).cpustat[CPUTIME_IDLE];
108	}
109	
110	static u64 wn_iowait_ns(int cpu)
111	{
112		u64 us;
113	
114		if (!cpu_online(cpu))
115			return kcpustat_cpu(cpu).cpustat[CPUTIME_IOWAIT];
116	
117		us = get_cpu_iowait_time_us(cpu, NULL);
118		if (us != (u64)-1)
119			return us * NSEC_PER_USEC_LOCAL;
120		return kcpustat_cpu(cpu).cpustat[CPUTIME_IOWAIT];
121	}
122	
123	/*
124	 * 上一轮各 CPU 的在线状态，用于判定累计值是否发生重置。
125	 *
126	 * 为什么要记：CPU 下线 → 上线时，内核在 tick_cancel_sched_timer() 里
127	 * memset 掉 tick_cpu_sched，idle/iowait 累计被清零后重新累加。
128	 * 快照表现为「累计值突然变小」。只要 online 状态与上一轮不同，
129	 * 就把 valid 置 0，让用户态跳过这一对快照。
130	 */
131	static u8 g_prev_online[WEAKNET_KMOD_MAX_CPUS];
132	static bool g_have_prev;
133	
134	/* 采集到私有缓冲区，不触碰共享区，避免长时间中断读者。 */
135	static void wn_collect(struct wn_cpu_snapshot *priv)
136	{
137		int cpu, n = 0;
138	
139		priv->hdr.abi_version = WEAKNET_KMOD_ABI_VERSION;
140		priv->hdr.sample_ns = ktime_get_ns();
141	
142		for_each_possible_cpu(cpu) {
143			struct wn_cpu_stat *r;
144			struct kernel_cpustat kcs;
145			u32 online;
146	
147			if (n >= (int)WEAKNET_KMOD_MAX_CPUS)
148				break;
149	
150			/*
151			 * 未开 CONFIG_VIRT_CPU_ACCOUNTING_GEN 时该函数是
152			 * *dst = kcpustat_cpu(cpu) 的内联展开。
153			 */
154			kcpustat_cpu_fetch(&kcs, cpu);
155	
156			online = cpu_online(cpu) ? 1u : 0u;
157	
158			r = &priv->cpu[n++];
159			r->cpu_id = (u32)cpu;
160			r->online = online;
161	
162			/*
163			 * 首轮没有可比对象，标 valid；此后只要在线状态发生变化
164			 * （下线或上线）就标 0，因为内核此时已经重置了累计值。
165			 */
166			if (!g_have_prev || g_prev_online[cpu] == online)
167				r->valid = 1u;
168			else
169				r->valid = 0u;
170			g_prev_online[cpu] = (u8)online;
171	
172			r->user = kcs.cpustat[CPUTIME_USER];
173			r->nice = kcs.cpustat[CPUTIME_NICE];
174			r->system = kcs.cpustat[CPUTIME_SYSTEM];
175			r->idle = wn_idle_ns(cpu);
176			r->iowait = wn_iowait_ns(cpu);
177			r->irq = kcs.cpustat[CPUTIME_IRQ];
178			r->softirq = kcs.cpustat[CPUTIME_SOFTIRQ];
179			r->steal = kcs.cpustat[CPUTIME_STEAL];
180			r->guest = kcs.cpustat[CPUTIME_GUEST];
181			r->guest_nice = kcs.cpustat[CPUTIME_GUEST_NICE];
182		}
183	
184		g_have_prev = true;
185		priv->hdr.nr_cpus = (u32)n;
186	}
187	
188	/*
189	 * seqlock 风格的发布：写窗口只覆盖一次 memcpy。
190	 * 奇数代次表示写入进行中，用户态读到即重试。
191	 */
192	static void wn_publish(struct wn_cpu_snapshot *dst,
193			       const struct wn_cpu_snapshot *src)
194	{
195		u64 s = READ_ONCE(dst->hdr.seq);
196		size_t bytes = src->hdr.nr_cpus * sizeof(struct wn_cpu_stat);
197	
198		WRITE_ONCE(dst->hdr.seq, s + 1);
199		smp_wmb();
200	
201		dst->hdr.abi_version = src->hdr.abi_version;
202		dst->hdr.sample_ns = src->hdr.sample_ns;
203		dst->hdr.nr_cpus = src->hdr.nr_cpus;
204		memcpy(dst->cpu, src->cpu, bytes);
205	
206		smp_wmb();
207		WRITE_ONCE(dst->hdr.seq, s + 2);
208	}
209	
210	static enum hrtimer_restart wn_timer_cb(struct hrtimer *t)
211	{
212		wn_collect(g_priv);
213		wn_publish(g_shared, g_priv);
214	
215		hrtimer_forward_now(t, g_interval);
216		return HRTIMER_RESTART;
217	}
218	
219	static int wn_open(struct inode *inode, struct file *file)
220	{
221		if (!capable(CAP_SYS_ADMIN))
222			return -EPERM;
223		return 0;
224	}
225	
226	static void wn_vma_close(struct vm_area_struct *vma)
227	{
228		module_put(THIS_MODULE);
229	}
230	
231	static const struct vm_operations_struct wn_vm_ops = {
232		.close = wn_vma_close,
233	};
234	
235	static int wn_mmap(struct file *file, struct vm_area_struct *vma)
236	{
237		unsigned long size = vma->vm_end - vma->vm_start;
238		int ret;
239	
240		/*
241		 * 只读映射：快照是内核单向发布的，用户态没有写它的理由。
242		 *
243		 * 缺了这一条时 PROT_WRITE 映射会被 remap_vmalloc_range 直接放行，
244		 * 用户态可以改写 hdr.seq / sample_ns 等字段。更糟的是 seqlock 挡不住：
245		 * 用户态自己就是写者，改完 seq 后读者照常采信，一致性保证被架空。
246		 */
247		if (vma->vm_flags & VM_WRITE)
248			return -EACCES;
249	
250		if (vma->vm_pgoff)
251			return -EINVAL;
252	
253		if (size > g_map_size) {
254			pr_err("%s: mmap size %lu exceeds %zu\n",
255			       DEVICE_NAME, size, g_map_size);
256			return -EINVAL;
257		}
258	
259		/* 映射存活期间禁止卸载，避免 vm_ops 回调进已释放的代码段。 */
260		if (!try_module_get(THIS_MODULE))
261			return -ENODEV;
262	
263		ret = remap_vmalloc_range(vma, g_shared, 0);
264		if (ret) {
265			module_put(THIS_MODULE);
266			return ret;
267		}
268	
269		vma->vm_ops = &wn_vm_ops;
270		return 0;
271	}
272	
273	static const struct file_operations wn_fops = {
274		.owner  = THIS_MODULE,
275		.open   = wn_open,
276		.mmap   = wn_mmap,
277		.llseek = no_llseek,
278	};
279	
280	static int __init wn_init(void)
281	{
282		int ret;
283	
284		BUILD_BUG_ON(NR_STATS < CPUTIME_GUEST_NICE + 1);
285		BUILD_BUG_ON(sizeof(struct wn_cpu_stat) % 8);
286	
287		g_map_size = PAGE_ALIGN(sizeof(struct wn_cpu_snapshot));
288	
289		g_shared = vmalloc_user(g_map_size);
290		if (!g_shared)
291			return -ENOMEM;
292	
293		g_priv = vmalloc(g_map_size);
294		if (!g_priv) {
295			ret = -ENOMEM;
296			goto err_free_shared;
297		}
298	
299		memset(g_priv, 0, g_map_size);
300		memset(g_shared, 0, g_map_size);
301	
302		/* 先采一次，保证用户态一打开就能读到有效数据。 */
303		wn_collect(g_priv);
304		wn_publish(g_shared, g_priv);
305	
306		ret = alloc_chrdev_region(&g_dev, 0, 1, DEVICE_NAME);
307		if (ret)
308			goto err_free_priv;
309	
310		cdev_init(&g_cdev, &wn_fops);
311		g_cdev.owner = THIS_MODULE;
312	
313		ret = cdev_add(&g_cdev, g_dev, 1);
314		if (ret)
315			goto err_unregister;
316	
317	#if LINUX_VERSION_CODE >= KERNEL_VERSION(6, 4, 0)
318		g_class = class_create(CLASS_NAME);
319	#else
320		g_class = class_create(THIS_MODULE, CLASS_NAME);
321	#endif
322		if (IS_ERR(g_class)) {
323			ret = PTR_ERR(g_class);
324			goto err_cdev_del;
325		}
326	
327		g_device = device_create(g_class, NULL, g_dev, NULL, DEVICE_NAME);
328		if (IS_ERR(g_device)) {
329			ret = PTR_ERR(g_device);
330			goto err_class_destroy;
331		}
332	
333		g_interval = ktime_set(1, 0);
334		hrtimer_init(&g_timer, CLOCK_MONOTONIC, HRTIMER_MODE_REL);
335		g_timer.function = wn_timer_cb;
336		hrtimer_start(&g_timer, g_interval, HRTIMER_MODE_REL);
337	
338		pr_info("%s: loaded, %d possible CPUs, map %zu bytes\n",
339			DEVICE_NAME, num_possible_cpus(), g_map_size);
340		return 0;
341	
342	err_class_destroy:
343		class_destroy(g_class);
344	err_cdev_del:
345		cdev_del(&g_cdev);
346	err_unregister:
347		unregister_chrdev_region(g_dev, 1);
348	err_free_priv:
349		vfree(g_priv);
350	err_free_shared:
351		vfree(g_shared);
352		return ret;
353	}
354	
355	static void __exit wn_exit(void)
356	{
357		hrtimer_cancel(&g_timer);
358	
359		device_destroy(g_class, g_dev);
360		class_destroy(g_class);
361		cdev_del(&g_cdev);
362		unregister_chrdev_region(g_dev, 1);
363	
364		vfree(g_priv);
365		vfree(g_shared);
366	
367		pr_info("%s: unloaded\n", DEVICE_NAME);
368	}
369	
370	module_init(wn_init);
371	module_exit(wn_exit);

