 45	        case MetricId::TCP_LOSS_RATE: return "tcp_loss_rate";
 46	        case MetricId::WIFI_LOSS_RATE: return "wifi_loss_rate";
 47	        case MetricId::RSSI_DBM: return "rssi_dbm";
 48	        case MetricId::TRAFFIC_BPS: return "traffic_bps";
 49	        case MetricId::TRAFFIC_PPS: return "traffic_pps";
 50	        case MetricId::TRAFFIC_FLOWS: return "traffic_flows";
 51	        case MetricId::BAND_CONFLICT: return "band_conflict";
 52	        case MetricId::DNS_QUERIES: return "dns_queries";
 53	        case MetricId::DNS_FAILURE_RATIO: return "dns_failure_ratio";
 54	        case MetricId::DNS_LATENCY_P50_MS: return "dns_latency_p50_ms";
 55	        case MetricId::DNS_INFLIGHT: return "dns_inflight";
 56	        case MetricId::TCP_RETRANS_LOSS_PCT: return "tcp_retrans_loss_pct";
 57	        case MetricId::TCP_CONN_ACTIVE: return "tcp_conn_active";
 58	        case MetricId::TCP_CONN_ACCEPT_RATE: return "tcp_conn_accept_rate";
 59	        case MetricId::CPU_BUSY_RATIO: return "cpu_busy_ratio";
 60	        default: return "unknown";
 61	    }
 62	}
 63	
 64	enum class MetricState {
 65	    VALID,
 66	    STALE,
 67	    UNAVAILABLE,
 68	    NOT_APPLICABLE,
 69	    ERROR
 70	};
 71	
 72	inline const char* metricStateToString(MetricState state) {
 73	    switch (state) {
 74	        case MetricState::VALID: return "VALID";
 75	        case MetricState::STALE: return "STALE";
 76	        case MetricState::UNAVAILABLE: return "UNAVAILABLE";
 77	        case MetricState::NOT_APPLICABLE: return "NOT_APPLICABLE";
 78	        case MetricState::ERROR: return "ERROR";
 79	        default: return "UNKNOWN";
 80	    }
 81	}
 82	
 83	enum class MetricUnit {
 84	    MILLISECONDS,
 85	    PERCENT,
 86	    DBM,
 87	    BYTES_PER_SEC,
 88	    PACKETS_PER_SEC,
 89	    COUNT,
 90	    BOOLEAN
 91	};
 92	
 93	enum class MetricScope {
 94	    INTERFACE,
 95	    GLOBAL,
 96	    HOST,
 97	    RESOLVER
 98	};
 99	
100	enum class SourceSemantics {
101	    GAUGE,
102	    EVENT,
103	    INTERVAL_DELTA_RATE,
104	    CUMULATIVE_COUNTER
105	};
106	
107	enum class PublishedSemantics {
108	    GAUGE,
109	    EVENT,
110	    INTERVAL_RATE
111	};
112	
113	struct MetricDescriptor {
114	    MetricId id;
115	    std::string name;
116	    MetricUnit unit;
117	    MetricScope scope;
118	    SourceSemantics source_semantics;
119	    PublishedSemantics published_semantics;
120	    std::chrono::milliseconds expected_interval;
121	    std::chrono::milliseconds freshness;
122	};
123	
124	inline MetricDescriptor getMetricDescriptor(MetricId id) {
125	    using namespace std::chrono_literals;
126	    switch (id) {
127	        case MetricId::RTT_MS:
128	            return {MetricId::RTT_MS, "rtt_ms", MetricUnit::MILLISECONDS, MetricScope::INTERFACE,
129	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
130	        case MetricId::REACHABILITY_SUCCESS:
131	            return {MetricId::REACHABILITY_SUCCESS, "reachability_success", MetricUnit::BOOLEAN, MetricScope::INTERFACE,
132	                    SourceSemantics::EVENT, PublishedSemantics::EVENT, 10000ms, 30000ms};
133	        case MetricId::JITTER_MS:
134	            return {MetricId::JITTER_MS, "jitter_ms", MetricUnit::MILLISECONDS, MetricScope::INTERFACE,
135	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
136	        case MetricId::TCP_LOSS_RATE:
137	            return {MetricId::TCP_LOSS_RATE, "tcp_loss_rate", MetricUnit::PERCENT, MetricScope::INTERFACE,
138	                    SourceSemantics::INTERVAL_DELTA_RATE, PublishedSemantics::INTERVAL_RATE, 10000ms, 30000ms};
139	        case MetricId::WIFI_LOSS_RATE:
140	            return {MetricId::WIFI_LOSS_RATE, "wifi_loss_rate", MetricUnit::PERCENT, MetricScope::INTERFACE,
141	                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::INTERVAL_RATE, 10000ms, 30000ms};
142	        case MetricId::RSSI_DBM:
143	            return {MetricId::RSSI_DBM, "rssi_dbm", MetricUnit::DBM, MetricScope::INTERFACE,
144	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
145	        case MetricId::TRAFFIC_BPS:
146	            return {MetricId::TRAFFIC_BPS, "traffic_bps", MetricUnit::BYTES_PER_SEC, MetricScope::INTERFACE,
147	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
148	        case MetricId::TRAFFIC_PPS:
149	            return {MetricId::TRAFFIC_PPS, "traffic_pps", MetricUnit::PACKETS_PER_SEC, MetricScope::INTERFACE,
150	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
151	        case MetricId::TRAFFIC_FLOWS:
152	            return {MetricId::TRAFFIC_FLOWS, "traffic_flows", MetricUnit::COUNT, MetricScope::INTERFACE,
153	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
154	        case MetricId::BAND_CONFLICT:
155	            return {MetricId::BAND_CONFLICT, "band_conflict", MetricUnit::BOOLEAN, MetricScope::INTERFACE,
156	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
157	        case MetricId::DNS_QUERIES:
158	            return {MetricId::DNS_QUERIES, "dns_queries", MetricUnit::COUNT, MetricScope::GLOBAL,
159	                    SourceSemantics::EVENT, PublishedSemantics::EVENT, 10000ms, 30000ms};
160	        case MetricId::DNS_FAILURE_RATIO:
161	            return {MetricId::DNS_FAILURE_RATIO, "dns_failure_ratio", MetricUnit::PERCENT, MetricScope::GLOBAL,
162	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
163	        case MetricId::DNS_LATENCY_P50_MS:
164	            return {MetricId::DNS_LATENCY_P50_MS, "dns_latency_p50_ms", MetricUnit::MILLISECONDS, MetricScope::GLOBAL,
165	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
166	        case MetricId::DNS_INFLIGHT:
167	            return {MetricId::DNS_INFLIGHT, "dns_inflight", MetricUnit::COUNT, MetricScope::GLOBAL,
168	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
169	        case MetricId::TCP_RETRANS_LOSS_PCT:
170	            return {MetricId::TCP_RETRANS_LOSS_PCT, "tcp_retrans_loss_pct", MetricUnit::PERCENT, MetricScope::GLOBAL,
171	                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::INTERVAL_RATE, 10000ms, 30000ms};
172	        case MetricId::TCP_CONN_ACTIVE:
173	            return {MetricId::TCP_CONN_ACTIVE, "tcp_conn_active", MetricUnit::COUNT, MetricScope::GLOBAL,
174	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
175	        case MetricId::TCP_CONN_ACCEPT_RATE:
176	            return {MetricId::TCP_CONN_ACCEPT_RATE, "tcp_conn_accept_rate", MetricUnit::COUNT, MetricScope::GLOBAL,
177	                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::INTERVAL_RATE, 10000ms, 30000ms};
178	        case MetricId::CPU_BUSY_RATIO:
179	            /*
180	             * HOST 域首个投入使用的指标（MetricScope::HOST 在此之前只有
181	             * metrics_registry.hpp 的 scopeKey() 拼接逻辑，从无指标使用）。
182	             *
183	             * 语义：全系统 CPU 忙碌占比 0~1（多核按累计时间加权，不是算术平均，
184	             * 避免单核打满被 8 核平均稀释掉）。
185	             *
186	             * GAUGE：源数据是 /dev/weaknet_cpu_stat 的**累计**纳秒，但本驱动的
187	             * 插件内部已经做了区间差值并只发布比率，因此对外粒度是瞬时值。
188	             * 采样周期与 quality 线程对齐（15s），freshness 给两个周期，
189	             * 容许一次抖动而不至于让下游立刻判 STALE。
190	             */
191	            return {MetricId::CPU_BUSY_RATIO, "cpu_busy_ratio", MetricUnit::PERCENT, MetricScope::HOST,
192	                    SourceSemantics::CUMULATIVE_COUNTER, PublishedSemantics::GAUGE, 15000ms, 30000ms};
193	        default:
194	            return {id, "unknown", MetricUnit::COUNT, MetricScope::INTERFACE,
195	                    SourceSemantics::GAUGE, PublishedSemantics::GAUGE, 10000ms, 30000ms};
196	    }
197	}
