     1	/**
     2	 * @file test_observer_attribution_gtest.cpp
     3	 * @brief 观测者降级归因真值表 + CPU 采样器降级语义
     4	 *
     5	 * 覆盖两类必须钉死的语义：
     6	 *   1. 归因四分支 —— 必须能在证据上区分"网络真的坏了"与"采集端自己过载"，
     7	 *                    且数据缺失时绝不猜。
     8	 *   2. 采样器降级 —— 设备节点不存在时必须报不可用，**不得回落成 0**。
     9	 *                    0 会被下游解读成"CPU 很闲"，从而掩盖真实故障。
    10	 */
    11	
    12	#include <gtest/gtest.h>
    13	
    14	#include "assurance/observer_attribution.hpp"
    15	#include "host_pressure_monitor.hpp"
    16	
    17	using namespace weaknet;
    18	using namespace weaknet_dbus;
    19	
    20	namespace {
    21	
    22	/// 造一个"报 observer 降级"的 SLE 结果
    23	SleResult makeDegraded(const std::string& reason) {
    24	    SleResult s;
    25	    s.state = HealthState::UNKNOWN;
    26	    s.coverage = Coverage::PARTIAL;
    27	    s.reason = reason;
    28	    return s;
    29	}
    30	
    31	}  // namespace
    32	
    33	// ---------------------------------------------------------------------------
    34	// 1. 不涉及 observer 的 SLE → 不归因
    35	// ---------------------------------------------------------------------------
    36	
    37	TEST(ObserverAttribution, HealthyObservationIsNotAttributed) {
    38	    SleResult s;
    39	    s.state = HealthState::GOOD;
    40	    s.reason = "dns_resolution_healthy";
    41	
    42	    auto r = attributeObserverDegradation(s, "dns_service", 0.99, true);
    43	
    44	    EXPECT_EQ(r.attribution, ObserverAttribution::NONE);
    45	    EXPECT_FALSE(r.evaluated);
    46	    EXPECT_TRUE(r.evidence.empty());
    47	    EXPECT_EQ(r.trigger_sle, "dns_service");
    48	    // 原始 reason 必须原样保留，绝不被改写
    49	    EXPECT_EQ(r.observer_reason, "dns_resolution_healthy");
    50	}
    51	
    52	TEST(ObserverAttribution, UnknownWithoutObserverReasonIsNotAttributed) {
    53	    // 只是"没观测到"，不是"观测不可靠"。两者不可混为一谈：
    54	    // 前者 CPU 再忙也与归因无关，乱归因会让 UNKNOWN 变成噪声。
    55	    SleResult s;
    56	    s.state = HealthState::UNKNOWN;
    57	    s.reason = "no_dns_observations";
    58	
    59	    auto r = attributeObserverDegradation(s, "dns_service", 0.99, true);
    60	
    61	    EXPECT_EQ(r.attribution, ObserverAttribution::NONE);
    62	    EXPECT_FALSE(r.evaluated);
    63	}
    64	
    65	// ---------------------------------------------------------------------------
    66	// 2. observer 降级 × 无 CPU 数据 → UNATTRIBUTED（不猜）
    67	// ---------------------------------------------------------------------------
    68	
    69	TEST(ObserverAttribution, DegradedWithoutCpuDataIsUnattributed) {
    70	    auto s = makeDegraded("observer_unreliable_capture_emit_failure");
    71	
    72	    auto r = attributeObserverDegradation(s, "dns_service", 0.0, false);
    73	
    74	    EXPECT_EQ(r.attribution, ObserverAttribution::UNATTRIBUTED);
    75	    EXPECT_TRUE(r.evaluated);
    76	    EXPECT_FALSE(r.cpu_available);
    77	    // 缺数据时不能被当成"CPU 正常"：那会把本机问题甩给网络
    78	    EXPECT_NE(r.attribution, ObserverAttribution::NOT_HOST_CPU_BOUND);
    79	    // 也不能被当成"CPU 过载"：那是凭空指控
    80	    EXPECT_NE(r.attribution, ObserverAttribution::SELF_INFLICTED);
