 55	class RuleLoader {
 56	public:
 57	    static DiagnosisRule createRuleDnsBurstTimeout() {
 58	        DiagnosisRule r;
 59	        r.id = "RULE_DNS_CRITICAL_BURST_TIMEOUTS";
 60	        r.domain = "DNS_SERVICE";
 61	        r.priority = 80;
 62	        r.suppresses = {"RULE_DNS_SLOW_LATENCY"};
 63	        r.coexists_with = {"RULE_WIFI_WEAK_SIGNAL"};
 64	        r.trigger_sle = "dns_service";
 65	        r.trigger_reason = "critical_burst_timeouts";
 66	
 67	        // 前置条件: ip_reachability.state == "GOOD"
 68	        r.preconditions.logic = PredicateGroup::Logic::All;
 69	        r.preconditions.predicates.push_back({"ip_reachability.state", PredicateOp::Eq, std::string("GOOD")});
 70	
 71	        // 置信度升级
 72	        r.base_confidence = DiagnosisConfidence::MEDIUM;
 73	        r.upgrade_to_high_if.logic = PredicateGroup::Logic::All;
 74	        r.upgrade_to_high_if.predicates.push_back({"ip_reachability.state", PredicateOp::Eq, std::string("GOOD")});
 75	        r.upgrade_to_high_if.predicates.push_back({"dns.consecutive_timeouts", PredicateOp::Gte, 3.0});
 76	
 77	        r.hypothesis = "本地网关及物理链路正常，但配置的上游 DNS 解析器连续超时，无任何成功应答";
 78	
 79	        // 机器判定排除项
 80	        ExcludedCandidateRule ec1;
 81	        ec1.cause = "WEAK_WIFI_SIGNAL";
 82	        ec1.when.logic = PredicateGroup::Logic::All;
 83	        ec1.when.predicates.push_back({"link_type", PredicateOp::Eq, std::string("WIFI")});
 84	        ec1.when.predicates.push_back({"rf_health.rssi_dbm", PredicateOp::Gt, -65.0});
 85	        ec1.explanation = "空口 Wi-Fi 信号极佳 (RSSI > -65dBm)";
 86	        r.excluded_candidates.push_back(std::move(ec1));
 87	
 88	        ExcludedCandidateRule ec2;
 89	        ec2.cause = "GATEWAY_UNREACHABLE";
 90	        ec2.when.logic = PredicateGroup::Logic::All;
 91	        ec2.when.predicates.push_back({"ip_reachability.state", PredicateOp::Eq, std::string("GOOD")});
