160	
161	    static void validateRuleSet(const std::vector<DiagnosisRule>& rules) {
162	        std::set<std::string> rule_ids;
163	        for (const auto& r : rules) {
164	            if (r.id.empty()) {
165	                throw std::runtime_error("Rule ID cannot be empty");
166	            }
167	            if (!rule_ids.insert(r.id).second) {
168	                throw std::runtime_error("Duplicate rule ID: " + r.id);
169	            }
170	            if (r.domain.empty()) {
171	                throw std::runtime_error("Rule domain cannot be empty: " + r.id);
172	            }
173	        }
174	
175	        // 检测抑制环 (Cycle Detection)
176	        for (const auto& r : rules) {
177	            for (const auto& target_id : r.suppresses) {
178	                if (target_id == r.id) {
179	                    throw std::runtime_error("Self-suppression cycle detected: " + r.id);
180	                }
181	                // 检查双向直接循环 A suppresses B and B suppresses A
182	                for (const auto& other : rules) {
183	                    if (other.id == target_id) {
184	                        for (const auto& other_suppress : other.suppresses) {
185	                            if (other_suppress == r.id) {
186	                                throw std::runtime_error("Direct suppression cycle between " + r.id + " and " + other.id);
187	                            }
188	                        }
189	                    }
190	                }
191	            }
192	        }
193	    }
