    11	struct DnsEvaluatorConfig {
    12	    double error_ratio_degraded{0.05};               // 失败率 >= 5% -> DEGRADED
    13	    double error_ratio_bad{0.20};                    // 失败率 >= 20% -> BAD
    14	    // W3 校准：原工程初值 150ms 偏紧，跨公网真实递归时延常在 80~180ms 间波动，
    15	    // 会导致无丢包零失败的健康 DNS 频繁被置为 DEGRADED。校准后定为 200ms。
    16	    double median_latency_degraded_ms{200.0};        // 中位数时延 >= 200ms -> DEGRADED
    17	    double median_latency_bad_ms{500.0};             // 中位数时延 >= 500ms -> BAD
    18	    uint64_t min_terminals_for_evaluation{5};        // 最少终态事务门禁
    19	    double min_classification_coverage{0.70};        // SR-8: 分类覆盖率门禁 (evaluable / (evaluable + other + truncated))
    20	
    21	    // SR-9 突发连续超时单杀规则（修正 #1）
    22	    size_t critical_timeout_count{3};                // 连续 3 次超时
    23	    std::chrono::milliseconds critical_window{15000};// 15s 窗口内
    24	
    25	    // Observer 质量门禁：观测器自身丢证据时不允许把观测缺陷伪装成 DNS 故障。
    26	    // 直接负面证据（SERVFAIL/REFUSED）不受观测丢失影响，仍可成立；只有
    27	    // absence-derived 的超时判定会被观测丢失污染。阈值由真机负载矩阵校准得出。
    28	    double max_capture_emit_failure_ratio{0.02};     // BPF capture 输出失败率上限
    29	    double max_perf_delivery_loss_ratio{0.02};       // perf buffer 投递丢失率上限
    30	    double max_ambiguity_ratio{0.10};                // 匹配歧义率上限
    31	    double max_insert_failure_ratio{0.02};           // Tracker 容量溢出率上限
    32	    uint64_t observer_min_capture_attempts{20};      // 观测质量门禁的最小样本量
    33	
    34	    // 授予 capability-level 否决权所需的**最少不同 QNAME 数**。
    35	    // 单个域名的权威链路异常也会导致该域名长时间无响应，但那不是
    36	    // 本机解析能力故障；只有多个不同域名同时失败才足以证明能力失效。
    37	    uint64_t capability_min_distinct_qnames{2};
    38	};
    39	
    40	/**
    41	 * @brief DNS 服务健康 SLE 评估器 (无状态纯函数，SR-2, SR-9, SR-10, SR-14)
    42	 *
    43	 * 核心逻辑：
    44	 * 1. Missingness 三态判定 (SR-13 物理依据):
    45	 *    - query_started == 0 && inflight == 0 -> UNKNOWN(no_dns_observations) [绝不伪造 GOOD]
    46	 *    - inflight > 0 && evaluable_terminals == 0 -> UNKNOWN(awaiting_inflight)
    47	 *    - terminals > 0 但不足门禁 -> UNKNOWN(insufficient_terminal_observations)
    48	 * 2. SR-9 突发连续严重失败单杀判定 (修正 #1):
    49	 *    - 同一 binding_epoch
    50	 *    - >= 3 个独立事务 TIMEOUT_EXPIRED
    51	 *    - 全部在 critical_window (15s) 内
    52	 *    - 首尾两个 critical timeout 之间无任何 known_success terminal
    53	 * 3. 失败率与中位数时延评估:
    54	 *    - evaluable_terminals = known_success (NOERROR+NXDOMAIN) + known_failure (SERVFAIL+REFUSED+TIMEOUT)
    55	 *    - failure_ratio = known_failure / evaluable_terminals
    56	 *    - OTHER 和 TRUNCATED 不稀释 failure_ratio (SR-1, SR-14)
    57	 *    - 计算有效时延的中位数 (p50)
    58	 * 4. Tracking Quality 降级门禁 (SR-8):
    59	 *    - classification_coverage 过低 -> UNKNOWN (insufficient_classified_outcomes)
    60	 *
--- 120-300 ---
     1	        }
     2	
     3	        // 4. Tracking Quality 覆盖度检查 (SR-8)
     4	        double coverage_ratio = window.classificationCoverage();
     5	        if (coverage_ratio < cfg.min_classification_coverage) {
     6	            res.state = HealthState::UNKNOWN;
     7	            res.coverage = Coverage::PARTIAL;
     8	            res.reason = "insufficient_classified_outcomes";
     9	            res.evidence.push_back({"classification_coverage", coverage_ratio, "Ratio of classified outcomes is below threshold"});
    10	            return res;
    11	        }
    12	
    13	        // 4b. Observer 质量评估。注意：这里**不立即返回**。
    14	        //     直接负面证据（SERVFAIL/REFUSED 等真实捕获的错误响应）即使观测覆盖不完美也成立，
    15	        //     只有"缺席推导"的故障（TIMEOUT）才会被观测丢失污染。
    16	        //     因此观测不可靠时：有直接坏证据 -> 继续裁决但降 coverage；
    17	        //                       无直接坏证据 -> UNKNOWN，绝不把观测缺陷伪装成 DNS 故障。
    18	        std::string observer_reason = checkObserverQuality(window, cfg);
    19	        const bool observer_unreliable = !observer_reason.empty();
    20	        const bool has_direct_negative = window.directNegativeEvidence() > 0;
    21	        if (observer_unreliable) {
    22	            res.evidence.push_back({"capture_emit_failure_ratio", window.captureEmitFailureRatio(),
    23	                                    "BPF capture emit failure ratio"});
    24	            res.evidence.push_back({"perf_delivery_loss_ratio", window.perfDeliveryLossRatio(),
    25	                                    "Perf buffer delivery loss ratio"});
    26	            res.evidence.push_back({"ambiguity_ratio", window.ambiguityRatio(),
    27	                                    "Transaction matching ambiguity ratio"});
    28	            res.evidence.push_back({"insert_failure_ratio", window.insertFailureRatio(),
    29	                                    "Tracker capacity overflow ratio"});
    30	        }
    31	        if (observer_unreliable && !has_direct_negative) {
    32	            res.state = HealthState::UNKNOWN;
    33	            res.coverage = Coverage::PARTIAL;
    34	            res.reason = observer_reason;
    35	            return res;
    36	        }
    37	
    38	        // coverage：观测不可靠但有直接坏证据时降级为 PARTIAL，故障结论仍成立
    39	        res.coverage = observer_unreliable ? Coverage::PARTIAL : Coverage::FULL_FOR_PROFILE;
    40	        if (observer_unreliable) {
    41	            res.evidence.push_back({"observer_warning", 1.0,
    42	                                    "Direct negative evidence is trustworthy, but observer quality is degraded"});
    43	        }
    44	
    45	        // 5. 失败率与时延中位数计算
    46	        double fail_ratio = window.failureRatio();
    47	        res.evidence.push_back({"failure_ratio", fail_ratio, "Ratio of failed terminals over evaluable terminals"});
    48	
    49	        double median_latency = 0.0;
    50	        if (!window.latencies_ms.empty()) {
