   125	    /**
   126	     * @brief 观测质量检查。返回空字符串表示观测可信；否则返回机器可读的降级原因。
   127	     *
   128	     * 两级传输分别计量（BPF capture 与 perf buffer），不合并成单一数字——
   129	     * 两者是否描述同一轮拥塞尚未验证，合并会掩盖真实边界。
   130	     * 样本不足时不做判定，避免小样本误判。
   131	     */
   132	    static std::string checkObserverQuality(const DnsMetricWindow& window, const Config& cfg) {
   133	        if (window.capture_attempts < cfg.observer_min_capture_attempts &&
   134	            window.delivered_events == 0) {
   135	            return {}; // 样本不足，不判定观测质量
   136	        }
   137	        if (window.captureEmitFailureRatio() > cfg.max_capture_emit_failure_ratio) {
   138	            return "observer_unreliable_capture_emit_failure";
   139	        }
   140	        if (window.perfDeliveryLossRatio() > cfg.max_perf_delivery_loss_ratio) {
   141	            return "observer_unreliable_event_loss";
   142	        }
   143	        if (window.ambiguityRatio() > cfg.max_ambiguity_ratio) {
   144	            return "observer_unreliable_ambiguity";
   145	        }
   146	        if (window.insertFailureRatio() > cfg.max_insert_failure_ratio) {
   147	            return "tracker_capacity_overflow";
   148	        }
   149	        return {};
   150	    }
