   152	    static bool checkCriticalTimeoutBypass(const std::vector<DnsTransactionRecord>& terminals,
   153	                                           uint64_t target_epoch,
   154	                                           size_t burst_count,
   155	                                           std::chrono::milliseconds window_dur,
   156	                                           std::chrono::steady_clock::time_point cutoff) {
   157	        if (terminals.size() < burst_count) return false;
   158	
   159	        // 从最新的记录往回看
   160	        size_t consecutive_timeouts = 0;
   161	        std::chrono::steady_clock::time_point newest_timeout;
   162	        std::chrono::steady_clock::time_point oldest_timeout;
   163	
   164	        for (auto it = terminals.rbegin(); it != terminals.rend(); ++it) {
   165	            const auto& rec = *it;
   166	            if (rec.binding_epoch != target_epoch) {
   167	                continue; // 跨 epoch 隔离
   168	            }
   169	
   170	            if (rec.state == DnsTransactionState::TIMEOUT_EXPIRED) {
   171	                if (consecutive_timeouts == 0) {
   172	                    newest_timeout = rec.completed_at;
   173	                }
   174	                oldest_timeout = rec.completed_at;
   175	                consecutive_timeouts++;
   176	
   177	                if (consecutive_timeouts >= burst_count) {
   178	                    // 检查全部在 window_dur 且距离 cutoff 不超时
   179	                    if (cutoff >= newest_timeout && (cutoff - oldest_timeout) <= window_dur) {
   180	                        return true;
   181	                    }

