 26	std::string nowUtc() {
 27	    const auto now = std::chrono::system_clock::now();
 28	    const std::time_t time = std::chrono::system_clock::to_time_t(now);
 29	    std::tm tm{};
 30	    gmtime_r(&time, &tm);
 31	    std::ostringstream out;
 32	    out << std::put_time(&tm, "%Y-%m-%dT%H:%M:%SZ");
 33	    return out.str();
 34	}
