 37	const char* monitorStateName(MonitorState state) {
 38	    switch (state) {
 39	    case MonitorState::Registered: return "registered";
 40	    case MonitorState::Initializing: return "initializing";
 41	    case MonitorState::Initialized: return "initialized";
 42	    case MonitorState::Starting: return "starting";
 43	    case MonitorState::Running: return "running";
 44	    case MonitorState::Stopping: return "stopping";
 45	    case MonitorState::Stopped: return "stopped";
 46	    case MonitorState::Failed: return "failed";
 47	    case MonitorState::ConfiguredDisabled: return "configured_disabled";
 48	    }
 49	    return "unknown";
 50	}
