 52	MonitorManager::MonitorManager(
 53	    ServerContext* ctx, std::vector<std::unique_ptr<IMonitorPlugin>> plugins)
 54	    : ctx_(ctx) {
 55	    entries_.reserve(plugins.size());
 56	    for (auto& plugin : plugins) {
 57	        if (!plugin) continue;
 58	        MonitorStatus status;
 59	        status.name = plugin->name() ? plugin->name() : "";
 60	        if (status.name.empty()) continue;
 61	        entries_.push_back(Entry{std::move(plugin), std::move(status)});
 62	    }
 63	    std::stable_sort(entries_.begin(), entries_.end(),
 64	        [](const Entry& lhs, const Entry& rhs) {
 65	            return lhs.plugin->order() < rhs.plugin->order();
 66	        });
 67	}
