 71	void MonitorManager::setOverridePath(std::string path) {
 72	    std::lock_guard<std::mutex> lock(mutex_);
 73	    override_path_ = std::move(path);
 74	}
 75	
 76	bool MonitorManager::saveOverrides(std::string* error) const {
 77	    std::lock_guard<std::mutex> lock(mutex_);
 78	    if (override_path_.empty()) {
 79	        if (error) *error = "runtime override path is empty";
 80	        return false;
 81	    }
 82	    std::vector<uint8_t> bytes;
 83	    bytes.push_back('W'); bytes.push_back('N'); bytes.push_back('R'); bytes.push_back('O');
 84	    serializeInt32(1, bytes);
 85	    for (const auto& entry : entries_) {
 86	        serializeString(entry.status.name, bytes);
 87	        serializeInt32(entry.status.desired_enabled ? 1 : 0, bytes);
 88	    }
 89	
 90	    // 写入数据目录（overrides 是持久化状态，不能走 serializer 的 /tmp 安全限制）。
 91	    const std::string tmp_path = override_path_ + ".tmp";
 92	    std::ofstream out(tmp_path, std::ios::binary | std::ios::trunc);
 93	    if (!out) {
 94	        if (error) *error = "cannot open override file for write: " + tmp_path;
 95	        return false;
 96	    }
 97	    out.write(reinterpret_cast<const char*>(bytes.data()), static_cast<std::streamsize>(bytes.size()));
 98	    out.flush();
 99	    // 强制刷盘，确保断电不会留下空文件或半写入
100	    out.close();
101	    if (!out) {
102	        if (error) *error = "cannot write override file: " + tmp_path;
103	        std::remove(tmp_path.c_str());
104	        return false;
105	    }
106	    // 同步到磁盘硬件
107	    int fd = open(tmp_path.c_str(), O_RDONLY);
108	    if (fd >= 0) {
109	        fsync(fd);
110	        close(fd);
111	    }
112	    if (std::rename(tmp_path.c_str(), override_path_.c_str()) != 0) {
113	        if (error) *error = "cannot commit override file: " + override_path_;
114	        std::remove(tmp_path.c_str());
115	        return false;
116	    }
117	    return true;
118	}
