171	bool MonitorManager::startConfigured() {
172	    std::lock_guard<std::mutex> lock(mutex_);
173	    if (started_ || stopped_) return false;
174	
175	    bool all_ok = true;
176	    for (auto& entry : entries_) {
177	        entry.status.state = MonitorState::Initializing;
178	        entry.status.error.clear();
179	        entry.status.changed_at = nowUtc();
180	        if (!entry.plugin->init(ctx_)) {
181	            entry.status.state = MonitorState::Failed;
182	            entry.status.error = "plugin initialization failed";
183	            all_ok = false;
184	            continue;
185	        }
186	        entry.status.state = MonitorState::Initialized;
187	        bool enabled = true;
188	        if (auto override_it = desired_overrides_.find(entry.status.name);
189	            override_it != desired_overrides_.end()) {
190	            enabled = override_it->second;
191	        } else if (ctx_ && !getMonitorEnabled(ctx_->cfg, entry.status.name, &enabled)) {
192	            entry.status.state = MonitorState::Failed;
193	            entry.status.error = "missing monitor configuration";
194	            all_ok = false;
195	            continue;
196	        }
197	        entry.status.desired_enabled = enabled;
198	        if (!enabled) entry.status.state = MonitorState::ConfiguredDisabled;
199	    }
200	
201	    bool progress = true;
202	    while (progress) {
203	        progress = false;
204	        for (auto& entry : entries_) {
205	            if (entry.status.state != MonitorState::Initialized) continue;
206	            bool waiting = false;
207	            bool unavailable = false;
208	            std::string unavailable_dependency;
209	            for (const auto& dependency : entry.plugin->dependencies()) {
210	                const auto* dependency_entry = findLocked(dependency);
211	                if (!dependency_entry || dependency_entry->status.state == MonitorState::ConfiguredDisabled ||
212	                    dependency_entry->status.state == MonitorState::Failed ||
213	                    dependency_entry->status.state == MonitorState::Stopped) {
214	                    unavailable = true;
215	                    unavailable_dependency = dependency;
216	                    break;
217	                }
218	                if (dependency_entry->status.state != MonitorState::Running) waiting = true;
219	            }
220	            if (unavailable) {
221	                entry.status.state = MonitorState::Failed;
222	                entry.status.error = "dependency is unavailable: " + unavailable_dependency;
223	                all_ok = false;
224	                progress = true;
225	                continue;
226	            }
227	            if (waiting) continue;
228	            entry.status.state = MonitorState::Starting;
229	            if (!entry.plugin->start(ctx_)) {
230	                entry.status.state = MonitorState::Failed;
231	                entry.status.error = "plugin start failed";
232	                all_ok = false;
233	                progress = true;
234	                continue;
235	            }
236	            entry.status.state = MonitorState::Running;
237	            entry.status.changed_at = nowUtc();
238	            ++entry.status.generation;
239	            progress = true;
240	        }
241	    }
242	    for (auto& entry : entries_) {
243	        if (entry.status.state == MonitorState::Initialized) {
244	            entry.status.state = MonitorState::Failed;
245	            entry.status.error = "dependency cycle or unavailable dependency";
246	            all_ok = false;
247	        }
248	    }
249	    started_ = true;
250	    return all_ok;
251	}
