299	bool MonitorManager::enable(const std::string& name, std::string* error) {
300	    std::unique_lock<std::mutex> lock(mutex_);
301	    auto* entry = findLocked(name);
302	    if (!entry) {
303	        if (error) *error = "unknown monitor: " + name;
304	        return false;
305	    }
306	    if (stopped_) {
307	        if (error) *error = "monitor manager is stopped";
308	        return false;
309	    }
310	    if (entry->status.state == MonitorState::Running) {
311	        if (error) *error = "monitor already running: " + name;
312	        return false;
313	    }
314	    for (const auto& dependency : entry->plugin->dependencies()) {
315	        const auto* dependency_entry = findLocked(dependency);
316	        if (!dependency_entry || dependency_entry->status.state != MonitorState::Running) {
317	            if (error) *error = "dependency is not running: " + dependency;
318	            return false;
319	        }
320	    }
321	    if (entry->status.state == MonitorState::Starting ||
322	        entry->status.state == MonitorState::Stopping) {
323	        if (error) *error = "monitor transition in progress: " + name;
324	        return false;
325	    }
326	    if (ctx_) {
327	        if (!setMonitorEnabled(&ctx_->cfg, name, true)) {
328	            if (error) *error = "monitor has no configurable enabled flag: " + name;
329	            return false;
330	        }
331	    }
332	    if (entry->status.state == MonitorState::Failed && !entry->plugin->init(ctx_)) {
333	        entry->status.error = "plugin re-initialization failed";
334	        entry->status.changed_at = nowUtc();
335	        if (error) *error = entry->status.error;
336	        return false;
337	    }
338	    entry->status.desired_enabled = true;
339	    entry->status.state = MonitorState::Starting;
340	    entry->status.error.clear();
341	    if (!entry->plugin->start(ctx_)) {
342	        entry->status.state = MonitorState::Failed;
343	        entry->status.error = "plugin start failed";
344	        entry->status.changed_at = nowUtc();
345	        if (error) *error = entry->status.error;
346	        return false;
347	    }
348	    entry->status.state = MonitorState::Running;
349	    entry->status.changed_at = nowUtc();
350	    ++entry->status.generation;
351	    const auto callback = state_change_cb_;
352	    const MonitorStatus status = entry->status;
353	    lock.unlock();
354	    invokeStateCallback(callback, status);
355	    return true;
356	}
