403	    std::unique_lock<std::mutex> lock(mutex_);
404	    auto* entry = findLocked(name);
405	    if (!entry) {
406	        if (error) *error = "unknown monitor: " + name;
407	        return false;
408	    }
409	    if (stopped_ || entry->status.state == MonitorState::Starting ||
410	        entry->status.state == MonitorState::Stopping) {
411	        if (error) *error = stopped_ ? "monitor manager is stopped"
412	                                     : "monitor transition in progress: " + name;
413	        return false;
414	    }
415	    for (const auto& dependency : entry->plugin->dependencies()) {
416	        const auto* dependency_entry = findLocked(dependency);
417	        if (!dependency_entry || dependency_entry->status.state != MonitorState::Running) {
418	            if (error) *error = "dependency is not running: " + dependency;
419	            return false;
420	        }
421	    }
422	    if (entry->status.state == MonitorState::Running ||
423	        entry->status.state == MonitorState::Failed) {
424	        entry->status.state = MonitorState::Stopping;
425	        entry->plugin->stop();
426	        entry->status.state = MonitorState::Stopped;
427	    }
428	    if (ctx_) {
429	        if (!setMonitorEnabled(&ctx_->cfg, name, true)) {
430	            if (error) *error = "monitor has no configurable enabled flag: " + name;
431	            return false;
432	        }
433	    }
434	    entry->status.desired_enabled = true;
435	    entry->status.state = MonitorState::Starting;
436	    entry->status.error.clear();
437	    if (!entry->plugin->start(ctx_)) {
438	        entry->status.state = MonitorState::Failed;
439	        entry->status.error = "plugin start failed";
440	        entry->status.changed_at = nowUtc();
441	        if (error) *error = entry->status.error;
442	        return false;
443	    }
