299	bool MonitorManager::enable(const std::string& name, std::string* error) {
300	    std::unique_lock<std::mutex> lock(mutex_);
301	    auto* entry = findLocked(name);
302	    if (!entry) {
303	        if (error) *error = "unknown monitor: " + name;
304	        return false;
305	    }
306	    if (stopped_) {
307	        if (error) *error = "monitor manager is stopped";
308	        return false;
309	    }
310	    if (entry->status.state == MonitorState::Running) {
311	        if (error) *error = "monitor already running: " + name;
312	        return false;
313	    }
314	    for (const auto& dependency : entry->plugin->dependencies()) {
315	        const auto* dependency_entry = findLocked(dependency);
316	        if (!dependency_entry || dependency_entry->status.state != MonitorState::Running) {
317	            if (error) *error = "dependency is not running: " + dependency;
318	            return false;
319	        }
320	    }
321	    if (entry->status.state == MonitorState::Starting ||
322	        entry->status.state == MonitorState::Stopping) {
323	        if (error) *error = "monitor transition in progress: " + name;
324	        return false;
325	    }
326	    if (ctx_) {
327	        if (!setMonitorEnabled(&ctx_->cfg, name, true)) {
328	            if (error) *error = "monitor has no configurable enabled flag: " + name;
329	            return false;
330	        }
331	    }
332	    if (entry->status.state == MonitorState::Failed && !entry->plugin->init(ctx_)) {
333	        entry->status.error = "plugin re-initialization failed";
334	        entry->status.changed_at = nowUtc();
335	        if (error) *error = entry->status.error;
336	        return false;
337	    }
338	    entry->status.desired_enabled = true;
339	    entry->status.state = MonitorState::Starting;
340	    entry->status.error.clear();
341	    if (!entry->plugin->start(ctx_)) {
342	        entry->status.state = MonitorState::Failed;
343	        entry->status.error = "plugin start failed";
344	        entry->status.changed_at = nowUtc();
345	        if (error) *error = entry->status.error;
346	        return false;
347	    }
348	    entry->status.state = MonitorState::Running;
349	    entry->status.changed_at = nowUtc();
350	    ++entry->status.generation;
351	    const auto callback = state_change_cb_;
352	    const MonitorStatus status = entry->status;
353	    lock.unlock();
354	    invokeStateCallback(callback, status);
355	    return true;
356	}
357	
358	bool MonitorManager::disable(const std::string& name, std::string* error) {
359	    std::unique_lock<std::mutex> lock(mutex_);
360	    auto* entry = findLocked(name);
361	    if (!entry) {
362	        if (error) *error = "unknown monitor: " + name;
363	        return false;
364	    }
365	    if (entry->status.state == MonitorState::Stopped ||
366	        entry->status.state == MonitorState::ConfiguredDisabled ||
367	        entry->status.state == MonitorState::Initialized) {
368	        if (error) *error = "monitor already stopped: " + name;
369	        return false;
370	    }
371	    if (entry->status.state != MonitorState::Running &&
372	        entry->status.state != MonitorState::Failed) {
373	        if (error) *error = "monitor is not stoppable: " + name;
374	        return false;
375	    }
376	    for (const auto& candidate : entries_) {
377	        for (const auto& dependency : candidate.plugin->dependencies()) {
378	            if (dependency == name && candidate.status.state == MonitorState::Running) {
379	                if (error) *error = "monitor is required by: " + candidate.status.name;
380	                return false;
381	            }
382	        }
383	    }
384	    if (ctx_) {
385	        if (!setMonitorEnabled(&ctx_->cfg, name, false)) {
386	            if (error) *error = "monitor has no configurable enabled flag: " + name;
387	            return false;
388	        }
389	    }
390	    entry->status.desired_enabled = false;
391	    entry->status.state = MonitorState::Stopping;
392	    entry->plugin->stop();
393	    entry->status.state = MonitorState::Stopped;
394	    entry->status.changed_at = nowUtc();
395	    const auto callback = state_change_cb_;
396	    const MonitorStatus status = entry->status;
397	    lock.unlock();
398	    invokeStateCallback(callback, status);
399	    return true;
400	}
401	
402	bool MonitorManager::restart(const std::string& name, std::string* error) {
403	    std::unique_lock<std::mutex> lock(mutex_);
404	    auto* entry = findLocked(name);
405	    if (!entry) {
406	        if (error) *error = "unknown monitor: " + name;
407	        return false;
408	    }
409	    if (stopped_ || entry->status.state == MonitorState::Starting ||
410	        entry->status.state == MonitorState::Stopping) {
411	        if (error) *error = stopped_ ? "monitor manager is stopped"
412	                                     : "monitor transition in progress: " + name;
413	        return false;
414	    }
415	    for (const auto& dependency : entry->plugin->dependencies()) {
416	        const auto* dependency_entry = findLocked(dependency);
417	        if (!dependency_entry || dependency_entry->status.state != MonitorState::Running) {
418	            if (error) *error = "dependency is not running: " + dependency;
419	            return false;
420	        }
421	    }
422	    if (entry->status.state == MonitorState::Running ||
423	        entry->status.state == MonitorState::Failed) {
424	        entry->status.state = MonitorState::Stopping;
425	        entry->plugin->stop();
426	        entry->status.state = MonitorState::Stopped;
427	    }
428	    if (ctx_) {
429	        if (!setMonitorEnabled(&ctx_->cfg, name, true)) {
430	            if (error) *error = "monitor has no configurable enabled flag: " + name;
431	            return false;
432	        }
433	    }
434	    entry->status.desired_enabled = true;
435	    entry->status.state = MonitorState::Starting;
436	    entry->status.error.clear();
437	    if (!entry->plugin->start(ctx_)) {
438	        entry->status.state = MonitorState::Failed;
439	        entry->status.error = "plugin start failed";
440	        entry->status.changed_at = nowUtc();
441	        if (error) *error = entry->status.error;
442	        return false;
443	    }
444	    entry->status.state = MonitorState::Running;
445	    entry->status.changed_at = nowUtc();
446	    ++entry->status.generation;
447	    const auto callback = state_change_cb_;
448	    const MonitorStatus status = entry->status;
449	    lock.unlock();
450	    invokeStateCallback(callback, status);
451	    return true;
452	}
