 32	class IfacePlugin : public IMonitorPlugin {
 33	    ServerContext* ctx_ = nullptr;
 34	    std::thread worker_;
 35	public:
 36	    const char* name() const override { return "iface"; }
 37	    int order() const override { return 0; }
 38	    bool init(ServerContext* ctx) override { ctx_ = ctx; return true; }
 39	    bool start(ServerContext* ctx) override {
 40	        ctx->iface_stop.store(false);
 41	        start_iface_monitor_thread(ctx, &worker_);
 42	        return true;
 43	    }
 44	    void stop() override {
 45	        if (!ctx_) return;
 46	        ctx_->iface_stop.store(true);
 47	        if (worker_.joinable()) worker_.join();
 48	    }
 49	};
