 75	// ---------------------------------------------------------------------------
 76	class RttPlugin : public IMonitorPlugin {
 77	    ServerContext* ctx_ = nullptr;
 78	    std::thread worker_;
 79	public:
 80	    const char* name() const override { return "rtt"; }
 81	    int order() const override { return 10; }
 82	    bool init(ServerContext* ctx) override { ctx_ = ctx; return true; }
 83	    bool start(ServerContext* ctx) override {
 84	        if (!ctx->cfg.rtt.enabled.load()) {
 85	            LOG_INFO(LogModule::RTT, "RTT monitor disabled by config");
 86	            return true;
 87	        }
 88	        ctx->rtt_stop.store(false);
 89	        start_rtt_monitor_thread(ctx, &worker_,
 90	            ctx->cfg.rtt.target.get(),
 91	            ctx->cfg.rtt.interval_ms.load(),
 92	            ctx->cfg.rtt.timeout_ms.load(),
 93	            ctx->cfg.rtt.window_size.load());
 94	        return true;
 95	    }
 96	    void stop() override {
 97	        if (!ctx_) return;
 98	        ctx_->rtt_stop.store(true);
 99	        if (worker_.joinable()) worker_.join();
100	        if (ctx_->weak_mgr) {
101	            ctx_->weak_mgr->markMetricUnavailable("rtt");
102	            // jitter 作为 rtt 的衍生指标同生命周期：rtt 停则 jitter 数据不可用
103	            ctx_->weak_mgr->markMetricUnavailable("jitter");
104	        }
105	    }
106	};
