 19	bool DbusService::handleSetMonitorParam(DBusConnection* conn, DBusMessage* msg) {
 20	    LOG_INFO(LogModule::DBUS, "handleSetMonitorParam called");
 21	
 22	    // 运行时调参能改变设备行为（例如 active_probe.targets 决定它主动连接谁），
 23	    // 因此与 ExecuteAction 同级：仅 root 可写。
 24	    if (!requireRootCaller(conn, msg, "SetMonitorParam")) return false;
 25	
 26	    DBusError err;
 27	    dbus_error_init(&err);
 28	    const char* key = nullptr;
 29	    const char* value = nullptr;
 30	
 31	    if (!dbus_message_get_args(msg, &err, DBUS_TYPE_STRING, &key,
 32	                               DBUS_TYPE_STRING, &value, DBUS_TYPE_INVALID)) {
 33	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam arg error: " << err.message);
 34	        dbus_error_free(&err);
 35	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Invalid arguments (expect: string key, string value)");
 36	        dbus_connection_send(conn, reply, nullptr);
 37	        dbus_message_unref(reply);
 38	        return false;
 39	    }
 40	    if (!key || !value) {
 41	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", "Null key or value");
 42	        dbus_connection_send(conn, reply, nullptr);
 43	        dbus_message_unref(reply);
 44	        return false;
 45	    }
 46	
 47	    LOG_INFO(LogModule::DBUS, "SetMonitorParam: " << key << " = " << value);
 48	    std::string cfg_err;
 49	
 50	    // TRIAL 中本地调参会让回滚基线失真（trial 期间改过的 key，回滚时
 51	    // prior_values 已含云端的 trial 前值；本地再写一遍，等回滚来时被
 52	    // 覆盖成 trial 前 —— 等于把运维在 trial 期间的合法改动吞掉）。
 53	    // 因此 TRIAL 中显式拒绝本地写，等 confirm/rollback 后再放开。
 54	    if (ctx_->config_txn &&
 55	        ctx_->config_txn->state() == weaknet_dbus::ConfigState::TRIAL) {
 56	        cfg_err = "trial_in_progress";
 57	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam rejected: " << cfg_err);
 58	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", cfg_err.c_str());
 59	        dbus_connection_send(conn, reply, nullptr);
 60	        dbus_message_unref(reply);
 61	        return false;
 62	    }
 63	
 64	    // ctx_->cfg 是线程安全配置，setMonitorParam 内部对目标字段做校验+原子写入
 65	    if (!setMonitorParam(&ctx_->cfg, key, value, &cfg_err)) {
 66	        LOG_ERROR(LogModule::DBUS, "SetMonitorParam rejected: " << cfg_err);
 67	        DBusMessage* reply = dbus_message_new_error(msg, "com.example.WeakNet.Error", cfg_err.c_str());
 68	        dbus_connection_send(conn, reply, nullptr);
 69	        dbus_message_unref(reply);
 70	        return false;
 71	    }
 72	
 73	    // 若修改的是 active_probe 参数，立即重载配置并下发至运行中的探测实例，使改动实时生效
 74	    if (std::string(key).rfind("active_probe.", 0) == 0) {
 75	        applyActiveProbeConfig(ctx_);
 76	    }
 77	
 78	    LOG_INFO(LogModule::DBUS, "SetMonitorParam applied: " << key << " = " << value);
 79	
 80	    // 本地调参同样是一条 L1 事实，且是唯一一条"未经云端队列"的写入路径：
 81	    // 云端没有 network_pending_actions 记录可关联，只能由回执自带
 82	    // key/value/generation，才能落成一行 execution_origin=LOCAL_OPERATION 的
 83	    // outcome，与云端下发动作同表可查（否则本地改动在云端只表现为
 84	    // config_generation 跳变，无从判断改了什么）。
 85	    // 放在成功分支之后——上面失败处均已 return，能走到这里状态确实已变更。
 86	    if (ctx_ && ctx_->edge_exporter) {
 87	        ctx_->edge_exporter->emitLocalConfigChange(
 88	            key, value, "local_dbus_set", ctx_->cfg.config_generation.load());
 89	    }
 90	
 91	    // 返回成功
 92	    DBusMessage* reply = dbus_message_new_method_return(msg);
 93	    if (!reply) return false;
 94	
 95	    const char* status = "ok";
 96	    DBusMessageIter reply_args;
 97	    dbus_message_iter_init_append(reply, &reply_args);
 98	    dbus_message_iter_append_basic(&reply_args, DBUS_TYPE_STRING, &status);
 99	    dbus_connection_send(conn, reply, nullptr);
100	    dbus_connection_flush(conn);
101	    dbus_message_unref(reply);
102	    return true;
103	}
