  1	bool loadWeakNetConfig(const std::string& path, WeakNetConfig* out, std::string* error) {
  2	    if (!out) return false;
  3	
  4	    std::ifstream in(path);
  5	    if (!in) {
  6	        // 文件不存在：返回 true，保持默认值（与现有无配置行为一致）
  7	        return true;
  8	    }
  9	
 10	    std::vector<Section> stack;   // 当前打开的 section 头栈
 11	    std::string line;
 12	    size_t line_no = 0;
 13	
 14	    while (std::getline(in, line)) {
 15	        ++line_no;
 16	        if (isBlankOrComment(line)) continue;
 17	
 18	        const size_t indent = line.find_first_not_of(' ');
 19	        const std::string trimmed = trim(stripInlineComment(line));
 20	        if (trimmed.empty()) continue;
 21	
 22	        // 以 ':' 结尾 → section 头
 23	        if (!trimmed.empty() && trimmed.back() == ':') {
 24	            std::string name = trim(trimmed.substr(0, trimmed.size() - 1));
 25	            if (name.empty()) {
 26	                *error = "line " + std::to_string(line_no) + ": empty section name";
 27	                return false;
 28	            }
 29	            // 弹出同级或更深层 section
 30	            while (!stack.empty() && stack.back().indent >= static_cast<int>(indent))
 31	                stack.pop_back();
 32	            stack.push_back({static_cast<int>(indent), name});
 33	            continue;
 34	        }
 35	
 36	        // key: value 行
 37	        size_t colon = trimmed.find(':');
 38	        if (colon == std::string::npos) {
 39	            *error = "line " + std::to_string(line_no) + ": expected 'key: value', got '" + trimmed + "'";
 40	            return false;
 41	        }
 42	        std::string key = trim(trimmed.substr(0, colon));
 43	        // 值先剥引号再 trim：stripQuotes 处理成对引号（见其文档注释），
 44	        // 保留引号内的空白语义，故顺序是 trim → stripQuotes → trim。
 45	        std::string value = trim(stripQuotes(trim(trimmed.substr(colon + 1))));
 46	
 47	        // 弹出同级或更深层 section，当前行属于栈顶
 48	        while (!stack.empty() && stack.back().indent >= static_cast<int>(indent))
 49	            stack.pop_back();
 50	
 51	        if (stack.empty()) {
 52	            *error = "line " + std::to_string(line_no) + ": unexpected top-level key '" + key + "'";
 53	            return false;
 54	        }
 55	
 56	        const std::string& section = stack.back().name;
 57	        if (section == "server") {
 58	            if (!applyServerField(out, key, value, error)) {
 59	                *error = "line " + std::to_string(line_no) + ": " + *error;
 60	                return false;
 61	            }
 62	        } else if (section == "edge") {
 63	            if (!applyEdgeField(out, key, value, error)) {
 64	                *error = "line " + std::to_string(line_no) + ": " + *error;
 65	                return false;
 66	            }
 67	        } else if (section == "monitors") {
 68	            *error = "line " + std::to_string(line_no)
 69	                   + ": monitor name must be a section (e.g. 'rtt:'), got inline key '" + key + "'";
 70	            return false;
 71	        } else {
 72	            // monitors 下的监控器名
 73	            if (!applyMonitorField(out, section, key, value, error)) {
 74	                *error = "line " + std::to_string(line_no) + ": " + *error;
 75	                return false;
 76	            }
 77	        }
 78	    }
 79	
 80	    // 全文件解析完再做 URL 策略校验：与键书写顺序无关（allow_insecure_http
 81	    // 写在 url 前后都生效）
 82	    if (!validateEdgeUrlPolicy(*out, error)) return false;
 83	
 84	    return true;
 85	}
