 93	// ---- IPv4 校验（复用 net_ping 的逻辑，这里做轻量版） ----
 94	bool isValidIPv4(const std::string& s) {
 95	    if (s.empty()) return false;
 96	    int dots = 0;
 97	    size_t start = 0;
 98	    for (size_t i = 0; i <= s.size(); ++i) {
 99	        if (i == s.size() || s[i] == '.') {
100	            if (i == start) return false;  // 空段
101	            if (i - start > 3) return false;
102	            for (size_t j = start; j < i; ++j) {
103	                if (!std::isdigit(static_cast<unsigned char>(s[j]))) return false;
104	            }
105	            int octet = std::stoi(s.substr(start, i - start));
106	            if (octet > 255) return false;
107	            if (i < s.size() && s[i] == '.') ++dots;
108	            start = i + 1;
109	        }
110	    }
111	    return dots == 3;
112	}
