 19	bool ConfigTransaction::startTrial(const WeakNetConfig& cfg, const std::string& key,
 20	                                    const std::string& new_value,
 21	                                    const std::string& action_id,
 22	                                    uint64_t generation, std::string* error) {
 23	    if (!isTrialableKeyImpl(key)) {
 24	        if (error) *error = "key not trialable: " + key;
 25	        return false;
 26	    }
 27	    std::lock_guard<std::mutex> lock(mutex_);
 28	    if (state_ == ConfigState::TRIAL) {
 29	        if (error) *error = "trial_in_progress";
 30	        return false;
 31	    }
 32	    if (generation <= last_applied_generation_.load()) {
 33	        if (error) *error = "stale_generation";
 34	        return false;
 35	    }
 36	
 37	    std::string prior;
 38	    if (!snapshotMonitorParamImpl(cfg, key, &prior)) {
 39	        if (error) *error = "cannot snapshot prior value for key: " + key;
 40	        return false;
 41	    }
 42	
 43	    const auto now = std::chrono::steady_clock::now();
 44	    trial_.armed_at = now;
 45	    trial_.deadline = now + window_;
 46	    trial_.deadline_extended = false;  // 每个 trial 的延长配额独立
 47	    trial_.generation = generation;
 48	    trial_.pending_action_id = action_id;
 49	    trial_.pending_keys.clear();
 50	    trial_.pending_keys[key] = new_value;
 51	    trial_.prior_values.clear();
 52	    trial_.prior_values[key] = prior;
 53	    state_ = ConfigState::TRIAL;
 54	
 55	    persistPriorValues();
 56	    return true;
 57	}
